import { CliParseExit, parseArgs } from './lib/cli_parser.mjs';
import { toPythonBool, writePythonLine } from './lib/python_print.mjs';
import { getProgramName } from './lib/program_name.mjs';

export function main(argv = process.argv) {
  const programName = getProgramName(argv[1]);

  try {
    const args = parseArgs(argv.slice(2), programName);
    const lookup = createBidirectionalLookup({ a: 1, b: 2, c: 3 });
    const result1 = lookup.containsKey(args.key);
    const result2 = lookup.inverse.containsKey(args.val);

    writePythonLine(toPythonBool(result1));
    writePythonLine(toPythonBool(result2));
    return 0;
  } catch (error) {
    if (error instanceof CliParseExit) {
      if (error.streamName === 'stdout') {
